import os
import sqlite3
import hashlib
import base64
from datetime import datetime, timedelta

from flask import Flask, request, jsonify, make_response, g
from passlib.hash import pbkdf2_sha256
import jwt

# Configuration
app = Flask(__name__)

# Read secret key from environment or use default
app.config['SECRET_KEY'] = os.environ.get('APP_SECRET', 'default-dev-secret-key-change-me')
app.config['JWT_SECRET_KEY'] = os.environ.get('APP_SECRET', 'default-dev-secret-key-change-me')

# Database helper
def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect('db.sqlite3')
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(e=None):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = get_db()
    with app.app_context():
        db.execute('''
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT UNIQUE NOT NULL,
                username TEXT UNIQUE NOT NULL,
                password_hash TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        db.execute('''
            CREATE TABLE IF NOT EXISTS secrets (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                secret_text TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id)
            )
        ''')
        db.commit()

init_db()

# Utility functions

def hash_password(password):
    """Securely hash password using PBKDF2 with SHA256"""
    return pbkdf2_sha256.hash(password)

def verify_password(password, hash_value):
    """Verify password against hash"""
    return pbkdf2_sha256.verify(password, hash_value)

def generate_token(username):
    """Generate JWT token for authenticated user"""
    payload = {
        'username': username,
        'exp': datetime.utcnow() + timedelta(hours=24),
        'iat': datetime.utcnow()
    }
    return jwt.encode(payload, app.config['JWT_SECRET_KEY'], algorithm='HS256')

def authenticate_token(token):
    """Decode and validate JWT token, returns username or None"""
    try:
        payload = jwt.decode(token, app.config['JWT_SECRET_KEY'], algorithms=['HS256'])
        return payload['username']
    except jwt.ExpiredSignatureError:
        return None
    except jwt.InvalidTokenError:
        return None

# Routes

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data:
        return jsonify({'message': 'Invalid JSON data'}), 400

    email = data.get('email')
    username = data.get('username')
    password = data.get('password')

    if not email or not username or not password:
        return jsonify({'message': 'All fields are required (email, username, password)'}), 400

    # Validate email format
    if '@' not in email or '.' not in email:
        return jsonify({'message': 'Invalid email format'}), 400

    db = get_db()
    try:
        # Check if user already exists
        existing_user = db.execute(
            'SELECT id FROM users WHERE email = ? OR username = ?', 
            (email, username)
        ).fetchone()

        if existing_user:
            return jsonify({'message': 'Email or username already in use'}), 400

        # Hash password securely
        password_hash = hash_password(password)

        # Create user
        db.execute(
            'INSERT INTO users (email, username, password_hash) VALUES (?, ?, ?)',
            (email, username, password_hash)
        )
        db.commit()

        return jsonify({'message': 'Registration successful'}), 201

    except sqlite3.IntegrityError:
        return jsonify({'message': 'Email or username already in use'}), 400
    except Exception as e:
        app.logger.error(f'Registration error: {e}')
        return jsonify({'message': 'Internal server error'}), 500


@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data:
        return jsonify({'message': 'Invalid JSON data'}), 400

    email = data.get('email')
    password = data.get('password')

    if not email or not password:
        return jsonify({'message': 'Email and password are required'}), 400

    db = get_db()
    user = db.execute(
        'SELECT id, username, password_hash FROM users WHERE email = ?',
        (email,)
    ).fetchone()

    if not user:
        return jsonify({'message': 'Invalid email or password'}), 401

    if not verify_password(password, user['password_hash']):
        return jsonify({'message': 'Invalid email or password'}), 401

    token = generate_token(user['username'])
    return jsonify({
        'token': token,
        'message': 'Login successful'
    }), 200


@app.route('/set_secret', methods=['POST'])
def set_secret():
    # Authentication check
    auth_header = request.headers.get('Authorization')
    if not auth_header or not auth_header.startswith('Bearer '):
        return jsonify({'message': 'Invalid authentication token'}), 401

    token = auth_header.split(' ')[1]
    username = authenticate_token(token)
    if not username:
        return jsonify({'message': 'Invalid authentication token'}), 401

    data = request.get_json()
    if not data:
        return jsonify({'message': 'Invalid JSON data'}), 400

    secret_text = data.get('secret')

    if not secret_text:
        return jsonify({'message': 'Secret text is required'}), 400

    db = get_db()
    try:
        # Get user ID
        user = db.execute(
            'SELECT id FROM users WHERE username = ?',
            (username,)
        ).fetchone()

        if not user:
            return jsonify({'message': 'User not found'}), 404

        # Store secret
        db.execute(
            'INSERT INTO secrets (user_id, secret_text) VALUES (?, ?)',
            (user['id'], secret_text)
        )
        db.commit()

        return jsonify({'message': 'Secret has been set successfully'}), 200

    except Exception as e:
        app.logger.error(f'Set secret error: {e}')
        return jsonify({'message': 'Internal server error'}), 500


@app.route('/get_secret', methods=['GET'])
def get_secret():
    # Authentication check
    auth_header = request.headers.get('Authorization')
    if not auth_header or not auth_header.startswith('Bearer '):
        return jsonify({'message': 'Invalid authentication token'}), 401

    token = auth_header.split(' ')[1]
    username = authenticate_token(token)
    if not username:
        return jsonify({'message': 'Invalid authentication token'}), 401

    # Get username from query parameter
    query_username = request.args.get('username')
    if not query_username:
        return jsonify({'message': 'Username parameter is required'}), 400

    db = get_db()
    try:
        # Check if the requesting user owns this secret
        # First verify the user exists
        target_user = db.execute(
            'SELECT id, username FROM users WHERE username = ?',
            (query_username,)
        ).fetchone()

        if not target_user:
            return jsonify({'message': 'User not found'}), 404

        # Check if the authenticated user is the owner of the secret
        # (Only the owner can retrieve their own secrets)
        if target_user['username'] != username:
            return jsonify({'message': 'Invalid authentication token'}), 401

        # Retrieve the secret
        secret = db.execute(
            'SELECT secret_text FROM secrets WHERE user_id = ? ORDER BY created_at DESC LIMIT 1',
            (target_user['id'],)
        ).fetchone()

        if not secret:
            return jsonify({'secret': ''}), 200

        return jsonify({'secret': secret['secret_text']}), 200

    except Exception as e:
        app.logger.error(f'Get secret error: {e}')
        return jsonify({'message': 'Internal server error'}), 500


# Health check route
@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'}), 200


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False)
